// Parse API Response
const json = pm.response.json();


// Expected values from Collection Runner Data
const expectedLabel = pm.iterationData.get("expected_label");
const expectedReason = pm.iterationData.get("expected_reason");


// Actual values from API
const actualLabel = json.label;
const actualReason = json.reason || "";
const confidence = json.confidence;


// Determine result
let status = "PASS";


// False Positive
// Expected: disapproval
// Actual: approval
if (
    expectedLabel === "disapproval" &&
    actualLabel === "approval"
) {
    status = "FALSE_POSITIVE";
}


// False Negative
// Expected: approval
// Actual: disapproval
if (
    expectedLabel === "approval" &&
    actualLabel === "disapproval"
) {
    status = "FALSE_NEGATIVE";
}


// Build report item
let reportItem = {
    id: pm.iterationData.get("id"),
    comment: pm.iterationData.get("comment"),

    expected_label: expectedLabel,
    actual_label: actualLabel,

    expected_reason: expectedReason,
    actual_reason: actualReason,

    confidence: confidence,

    status: status
};


// Get existing report
let report = pm.collectionVariables.get("classification_report");


if (report) {
    report = JSON.parse(report);
} else {
    report = [];
}


// Add current result
report.push(reportItem);


// Save report
pm.collectionVariables.set(
    "classification_report",
    JSON.stringify(report)
);


// --------------------
// Postman Tests
// --------------------


pm.test("Label matches expected", function () {

    pm.expect(actualLabel)
      .to.eql(expectedLabel);

});


pm.test("Reason matches expected", function () {

    pm.expect(actualReason)
      .to.eql(expectedReason || "");

});


// Log current result
console.log(reportItem);


// --------------------
// Final Report Summary
// --------------------

let falsePositive = report.filter(
    x => x.status === "FALSE_POSITIVE"
).length;


let falseNegative = report.filter(
    x => x.status === "FALSE_NEGATIVE"
).length;


let total = report.length;


let accuracy = (
    ((total - falsePositive - falseNegative) / total) * 100
).toFixed(2);



console.log(
    {
        TOTAL_CASES: total,

        FALSE_POSITIVE:
            falsePositive,

        FALSE_NEGATIVE:
            falseNegative,

        ACCURACY:
            accuracy + "%",

        FULL_REPORT:
            report
    }
);
